INSERT INTO `grades` (`code`, `name`, `level`, `order`, `is_active`, `created_at`, `updated_at`) VALUES ('4am', 'السنة الرابعة متوسط', 'moyen', 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `level` = VALUES(`level`), `order` = VALUES(`order`), `is_active` = VALUES(`is_active`), `updated_at` = NOW();
INSERT INTO `chapters` (`grade_id`, `code`, `title`, `topics`, `order`, `created_at`, `updated_at`) SELECT g.id, 'ansab_al_aadad_wal_hisab', 'ميدان أنساب الأعداد والحساب', '[{"id":"pgcd","title":"قواسم عدد طبيعي والقاسم المشترك الأكبر (PGCD) باستخدام خوارزمية أقليدس أو الفروق المتتالية","namedMethods":["خوارزمية أقليدس","الفروق المتتالية"]},{"id":"aadad_awwaliya","title":"الأعداد الأولية وكيفية كتابة كسر غير قابل للاختزال"},{"id":"hisab_judhur","title":"الحساب على الجذور التربيعية","namedParts":["الجمع","الضرب","القسمة","تبسيط عبارة"]},{"id":"nataqat_maqam","title":"ناطقة مقام نسبة وجذر تربيعي لعدد موجب"}]', 0, NOW(), NOW() FROM `grades` g WHERE g.code = '4am' ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `topics` = VALUES(`topics`), `order` = VALUES(`order`), `updated_at` = NOW();
INSERT INTO `units` (`chapter_id`, `code`, `title`, `subtitle`, `number`, `objectives`, `source_topic_codes`, `textbook`, `order`, `created_at`, `updated_at`) SELECT c.id, 'aadad-tabiiya-natiqa', 'الأعداد الطبيعيّة والأعداد النّاطقة', 'قواسم عدد طبيعي، القاسم المشترك الأكبر، العددان الأوليان فيما بينهما، اختزال كسر', 1, '["التعرّف على قاسم لعدد طبيعي.","تعيين مجموعة قواسم عدد طبيعي.","تعيين القاسم المشترك الأكبر لعددين طبيعيين.","التعرّف على عددين أوليين فيما بينهما.","كتابة كسر على الشكل غير القابل للاختزال."]', '["pgcd","aadad_awwaliya"]', '{"title":"كتاب الرياضيات — السنة الرابعة من التعليم المتوسط","generation":"الجيل الثاني","unit":1,"pages":"7–16","extraction":"docs\\/sources\\/4am\\/unit1\\/extraction.json"}', 0, NOW(), NOW() FROM `chapters` c JOIN `grades` g ON g.id = c.grade_id WHERE g.code = '4am' AND c.code = 'ansab_al_aadad_wal_hisab' ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `number` = VALUES(`number`), `objectives` = VALUES(`objectives`), `source_topic_codes` = VALUES(`source_topic_codes`), `textbook` = VALUES(`textbook`), `order` = VALUES(`order`), `updated_at` = NOW();
